INSERT INTO report_classes(tenant_id,id,subject,name,active,source,doc_json,created_at,created_by,updated_at,updated_by) SELECT tenant_id,'rcl_'||lower(hex(randomblob(12))),'art_exam','美术艺考',1,'template','{"name":"美术艺考","dimensions":[{"key":"d1","name":"素描造型","order":1,"feedback_tags":[]},{"key":"d2","name":"素描结构","order":2,"feedback_tags":[]},{"key":"d3","name":"素描明暗","order":3,"feedback_tags":[]},{"key":"d4","name":"素描画面","order":4,"feedback_tags":[]},{"key":"d5","name":"色彩色调","order":5,"feedback_tags":[]},{"key":"d6","name":"色彩冷暖","order":6,"feedback_tags":[]},{"key":"d7","name":"色彩塑造","order":7,"feedback_tags":[]},{"key":"d8","name":"速写动态","order":8,"feedback_tags":[]},{"key":"d9","name":"速写比例","order":9,"feedback_tags":[]},{"key":"d10","name":"速写线条","order":10,"feedback_tags":[]},{"key":"d11","name":"应试速度","order":11,"feedback_tags":[]}],"options":{"compare_previous":true,"mock_exam":true,"require_artwork":true,"renewal_suggestion":false},"subject":"art_exam"}',created_at,'migration0020',created_at,'migration0020' FROM tenant_subjects WHERE id='art_exam';
INSERT INTO report_dimensions(tenant_id,id,class_id,dim_key) SELECT c.tenant_id,'dim_'||lower(hex(randomblob(12))),c.id,json_extract(d.value,'$.key') FROM report_classes c,json_each(c.doc_json,'$.dimensions') d;
