-- 艺界星途阶段3：仅追加；0001–0019保持原样。
ALTER TABLE tenant_subjects ADD COLUMN imported_at INTEGER;
ALTER TABLE tenant_subjects ADD COLUMN content_json TEXT;
CREATE TABLE offer_courses(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,subject TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),source TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),price_cents INTEGER CHECK(price_cents IS NULL OR price_cents>=0),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE UNIQUE INDEX offer_courses_name ON offer_courses(tenant_id,subject,name) WHERE deleted_at IS NULL;
CREATE TABLE stage_types(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,subject TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),source TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE UNIQUE INDEX stage_types_name ON stage_types(tenant_id,subject,name) WHERE deleted_at IS NULL;
CREATE TABLE report_classes(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,subject TEXT NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),source TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE UNIQUE INDEX report_classes_name ON report_classes(tenant_id,subject,name) WHERE deleted_at IS NULL;
CREATE TABLE stage_rules(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE calendar_nodes(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE course_rules(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE tenant_profile(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE tenant_price_lists(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE report_dimensions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,class_id TEXT NOT NULL,dim_key TEXT NOT NULL,retired INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,class_id,dim_key),FOREIGN KEY(tenant_id,class_id) REFERENCES report_classes(tenant_id,id));
CREATE TABLE tenant_brand(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,qr_image_id TEXT,PRIMARY KEY(tenant_id,id));
CREATE TABLE gallery_images(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,r2_key TEXT NOT NULL,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,tags_json TEXT NOT NULL CHECK(json_valid(tags_json)),consent INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE setting_asset_refs(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,image_id TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,image_id) REFERENCES gallery_images(tenant_id,id));
CREATE INDEX setting_asset_image ON setting_asset_refs(tenant_id,image_id);
CREATE TABLE setting_imports(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,owner_id TEXT NOT NULL,rows_json TEXT NOT NULL CHECK(json_valid(rows_json)),price_rev INTEGER NOT NULL,expires_at INTEGER NOT NULL,consumed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,id));
CREATE TABLE ai_suggestions(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL,doc_json TEXT NOT NULL CHECK(json_valid(doc_json)),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id));
CREATE TABLE setting_changes(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,suggestion_id TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),before_json TEXT NOT NULL CHECK(json_valid(before_json)),after_json TEXT, status TEXT NOT NULL CHECK(status IN('pending','approved','rejected','reverted')),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,suggestion_id) REFERENCES ai_suggestions(tenant_id,id));
CREATE INDEX setting_changes_status ON setting_changes(tenant_id,status,created_at);
UPDATE students SET nickname=CASE WHEN trim(name)<>'' AND trim(name) NOT GLOB '*[^㐀-䶿一-鿿豈-﫿𠀀-𲎯]*' THEN CASE WHEN substr(trim(name),1,2) IN('欧阳','司马','上官','诸葛','夏侯','东方','皇甫','尉迟','公羊','赫连','澹台','公冶','宗政','濮阳','淳于','单于','太叔','申屠','公孙','仲孙','轩辕','令狐','钟离','宇文','长孙','慕容','司徒','司空','鲜于','闾丘','百里','东郭','南宫','西门','呼延','羊舌','微生','南门','第五','东门','端木','歐陽','司馬','諸葛','東方','尉遲','鍾離','鐘離','長孫','公孫','軒轅','閭丘','東郭','東門') THEN substr(trim(name),1,2) ELSE substr(trim(name),1,1) END||'同学' ELSE trim(name) END WHERE nickname='X 同学' OR trim(nickname)='';
CREATE TRIGGER student_nickname_insert AFTER INSERT ON students WHEN (NEW.nickname='X 同学' OR trim(NEW.nickname)='') AND NEW.nickname IS NOT (CASE WHEN trim(NEW.name)<>'' AND trim(NEW.name) NOT GLOB '*[^㐀-䶿一-鿿豈-﫿𠀀-𲎯]*' THEN CASE WHEN substr(trim(NEW.name),1,2) IN('欧阳','司马','上官','诸葛','夏侯','东方','皇甫','尉迟','公羊','赫连','澹台','公冶','宗政','濮阳','淳于','单于','太叔','申屠','公孙','仲孙','轩辕','令狐','钟离','宇文','长孙','慕容','司徒','司空','鲜于','闾丘','百里','东郭','南宫','西门','呼延','羊舌','微生','南门','第五','东门','端木','歐陽','司馬','諸葛','東方','尉遲','鍾離','鐘離','長孫','公孫','軒轅','閭丘','東郭','東門') THEN substr(trim(NEW.name),1,2) ELSE substr(trim(NEW.name),1,1) END||'同学' ELSE trim(NEW.name) END) BEGIN UPDATE students SET nickname=CASE WHEN trim(NEW.name)<>'' AND trim(NEW.name) NOT GLOB '*[^㐀-䶿一-鿿豈-﫿𠀀-𲎯]*' THEN CASE WHEN substr(trim(NEW.name),1,2) IN('欧阳','司马','上官','诸葛','夏侯','东方','皇甫','尉迟','公羊','赫连','澹台','公冶','宗政','濮阳','淳于','单于','太叔','申屠','公孙','仲孙','轩辕','令狐','钟离','宇文','长孙','慕容','司徒','司空','鲜于','闾丘','百里','东郭','南宫','西门','呼延','羊舌','微生','南门','第五','东门','端木','歐陽','司馬','諸葛','東方','尉遲','鍾離','鐘離','長孫','公孫','軒轅','閭丘','東郭','東門') THEN substr(trim(NEW.name),1,2) ELSE substr(trim(NEW.name),1,1) END||'同学' ELSE trim(NEW.name) END WHERE tenant_id=NEW.tenant_id AND id=NEW.id; END;
CREATE TRIGGER student_nickname_update AFTER UPDATE OF name,nickname ON students WHEN (NEW.nickname='X 同学' OR trim(NEW.nickname)='') AND NEW.nickname IS NOT (CASE WHEN trim(NEW.name)<>'' AND trim(NEW.name) NOT GLOB '*[^㐀-䶿一-鿿豈-﫿𠀀-𲎯]*' THEN CASE WHEN substr(trim(NEW.name),1,2) IN('欧阳','司马','上官','诸葛','夏侯','东方','皇甫','尉迟','公羊','赫连','澹台','公冶','宗政','濮阳','淳于','单于','太叔','申屠','公孙','仲孙','轩辕','令狐','钟离','宇文','长孙','慕容','司徒','司空','鲜于','闾丘','百里','东郭','南宫','西门','呼延','羊舌','微生','南门','第五','东门','端木','歐陽','司馬','諸葛','東方','尉遲','鍾離','鐘離','長孫','公孫','軒轅','閭丘','東郭','東門') THEN substr(trim(NEW.name),1,2) ELSE substr(trim(NEW.name),1,1) END||'同学' ELSE trim(NEW.name) END) BEGIN UPDATE students SET nickname=CASE WHEN trim(NEW.name)<>'' AND trim(NEW.name) NOT GLOB '*[^㐀-䶿一-鿿豈-﫿𠀀-𲎯]*' THEN CASE WHEN substr(trim(NEW.name),1,2) IN('欧阳','司马','上官','诸葛','夏侯','东方','皇甫','尉迟','公羊','赫连','澹台','公冶','宗政','濮阳','淳于','单于','太叔','申屠','公孙','仲孙','轩辕','令狐','钟离','宇文','长孙','慕容','司徒','司空','鲜于','闾丘','百里','东郭','南宫','西门','呼延','羊舌','微生','南门','第五','东门','端木','歐陽','司馬','諸葛','東方','尉遲','鍾離','鐘離','長孫','公孫','軒轅','閭丘','東郭','東門') THEN substr(trim(NEW.name),1,2) ELSE substr(trim(NEW.name),1,1) END||'同学' ELSE trim(NEW.name) END WHERE tenant_id=NEW.tenant_id AND id=NEW.id; END;

