INSERT OR IGNORE INTO tenant_price_lists(tenant_id,id,doc_json,created_at,created_by,updated_at,updated_by) SELECT tenant_id,'main','{}',created_at,'migration0020',created_at,'migration0020' FROM tenant_subjects WHERE id='art_exam';
UPDATE calendar_nodes SET doc_json=json_insert(doc_json,'$.items[#]',json('{"key":"summer_camp","name":"暑期集训","months":[7,8]}')) WHERE tenant_id IN(SELECT tenant_id FROM tenant_subjects WHERE id='art_exam') AND NOT EXISTS(SELECT 1 FROM json_each(calendar_nodes.doc_json,'$.items') WHERE json_extract(value,'$.key')='summer_camp');
UPDATE calendar_nodes SET doc_json=json_insert(doc_json,'$.items[#]',json('{"key":"unified_exam","name":"统考","months":[12],"note":"按省份改"}')) WHERE tenant_id IN(SELECT tenant_id FROM tenant_subjects WHERE id='art_exam') AND NOT EXISTS(SELECT 1 FROM json_each(calendar_nodes.doc_json,'$.items') WHERE json_extract(value,'$.key')='unified_exam');
UPDATE calendar_nodes SET doc_json=json_insert(doc_json,'$.items[#]',json('{"key":"school_exam","name":"校考","months":[1,2,3],"next_year":true}')) WHERE tenant_id IN(SELECT tenant_id FROM tenant_subjects WHERE id='art_exam') AND NOT EXISTS(SELECT 1 FROM json_each(calendar_nodes.doc_json,'$.items') WHERE json_extract(value,'$.key')='school_exam');
UPDATE tenant_subjects SET imported_at=created_at,content_json='{"content_types":[{"name":"集训招生","required":["时间","课程安排","师资","报名方式"],"optional":["画室环境","住宿与管理","往届成果"]},{"name":"统考 / 校考提醒","required":["关键日期","考试科目与时长","现在该做什么"],"optional":["政策解读（须机构提供文件）"]},{"name":"模拟考 / 讲评","required":["概况","高分卷展示"],"optional":["老师讲评要点"]},{"name":"合格与录取喜报","required":["祝贺","成绩概况"],"optional":["学员故事（须家长同意）"]},{"name":"画室作品展示","required":["作品","创作要点"],"optional":["教学理念"]}],"constraints":{"prohibited_terms":["包过","保录","100% 合格","第一","最好"],"policy_source":"只使用机构提供的官方文件","student_privacy":"默认姓氏或昵称；全名与照片需家长同意","report_basis":"只按老师要点与评分写，不推算分数、不和其他学员比较"},"tone":"专业、务实"}' WHERE id='art_exam';
